(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const crumb = document.querySelector('.pj-crumb-link');
  if (crumb) { crumb.click(); await sleep(1800); }
  return JSON.stringify({ atList: !!document.querySelector('.tb-project-main'), cards: document.querySelectorAll('.tb-project-main').length });
})()
